def sum_of_digits(numbers):
    def digit_sum(num):
        try:
            # Convert number to string, ignore negative sign, and sum up digits
            return sum(int(digit) for digit in str(abs(num)) if digit.isdigit())
        except (ValueError, TypeError):
            return 0

    # Apply digit_sum for every valid number in the list
    return sum(digit_sum(num) for num in numbers if isinstance(num, (int, float)))

# Example usage and tests:
assert sum_of_digits([10, 2, 56]) == 14
assert sum_of_digits([10, 20, 4, 5, 'b', 70, 'a']) == 19
assert sum_of_digits([123, 'abc', 4.56, -789]) == 48
assert sum_of_digits([]) == 0
assert sum_of_digits(['x', None, [1, 2]]) == 0
```

